/**
 * @file web_ui.c
 * @brief Registers the UI's generated asset table (web_ui_gen.c) with the
 *        http_server_manager catch-all. The UI is the WiCAN-Pro-style v2
 *        single-page app (one gzipped index.html, served at "/" and
 *        "/index.html"). ESPNetLink ships exactly one UI, so the WiCAN
 *        CONFIG_WICAN_WEBUI_* selector is gone.
 */
#include "web_ui.h"

#include "esp_log.h"
#include "http_server_manager.h"

static const char *TAG = "web_ui";

/* generated by gen_assets.py at build time */
extern const http_asset_t web_ui_assets[];

esp_err_t web_ui_register(void)
{
    esp_err_t err = http_server_manager_register_assets(web_ui_assets);

    if (err == ESP_OK)
    {
        ESP_LOGI(TAG, "web UI registered");
    }
    return err;
}
